SET client_min_messages = warning;

CREATE TABLE IF NOT EXISTS public.ottoq_throughput_sweep_arms (
  arm_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sweep_id uuid, cell_id uuid, seed bigint,
  replicate boolean DEFAULT false, sim_run_id uuid, ran_at timestamptz DEFAULT now(), complete boolean, wall_s numeric);

